 * }
 */
func smallestFromLeaf(root *TreeNode) string {
	ans := ""
	var dfs func(root *TreeNode, path string)
	dfs = func(root *TreeNode, path string) {
		if root == nil {
			return
		}
		path = string('a'+root.Val) + path
		if root.Left == nil && root.Right == nil {
			if ans == "" || path < ans {
				ans = path
			}
			return
		}
		dfs(root.Left, path)
		dfs(root.Right, path)
	}

	dfs(root, "")
	return ans
}

package io.github.leetcode.tree;

import io.github.leetcode.tree.TreeNodes.TreeNode;

public class SmallestStringStartingFromLeaf {

    String curSmall = "";

    public String smallestFromLeaf(TreeNode root) {
        getSmallestString(root, "");
        return curSmall;
    }

    public void getSmallestString(TreeNode root, String pre) {
        char c = (char) ('a' + root.val);
        String cur = c + pre;

        if (root.left == null && root.right == null) {
            if (curSmall.length() == 0) curSmall = cur;
            else if (cur.compareTo(curSmall) < 0) curSmall = cur;
            return;
        }
        if (root.left != null) getSmallestString(root.left, cur);
        if (root.right != null) getSmallestString(root.right, cur);
    }

}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    void smallestWord(TreeNode* root, string &ans, string curr){
        if(!root)
            return;

        curr=char(root->val+'a')+curr;

        if(!root->left and !root->right){
            if(ans=="" || curr<ans)
                ans=curr;
        }

        if(root->left)
            smallestWord(root->left, ans, curr);
        if(root->right)
            smallestWord(root->right, ans, curr);
    }

    string smallestFromLeaf(TreeNode* root) {
        string ans="";
        smallestWord(root, ans, "");
        return ans;
    }
};

class Solution {
    String ans = "~";
    public String smallestFromLeaf(TreeNode root) {
        dfs(root, new StringBuilder());
        return ans;
    }

    public void dfs(TreeNode node, StringBuilder sb) {
        if (node == null) return;
        sb.append((char)('a' + node.val));

        if (node.left == null && node.right == null) {
            sb.reverse();
            String S = sb.toString();
            sb.reverse();

            if (S.compareTo(ans) < 0)
                ans = S;
        }

        dfs(node.left, sb);
        dfs(node.right, sb);
        sb.deleteCharAt(sb.length() - 1);
    }
}

class Solution(object):
    def smallestFromLeaf(self, root):
        self.ans = "~"

        def dfs(node, A):
            if node:
                A.append(chr(node.val + ord('a')))
                if not node.left and not node.right:
                    self.ans = min(self.ans, "".join(reversed(A)))

                dfs(node.left, A)
                dfs(node.right, A)
                A.pop()

        dfs(root, [])
        return self.ans
